#include "stdafx.h"#include "ListValue.h"#include <ConnectH.h>HANDLE GiveSem( const char* name ){  char szSem[32];  sprintf_s( szSem, sizeof(szSem), "HONEYWELL_CB_Sem_%s", name );  HANDLE hSem = ::OpenSemaphore( SEMAPHORE_ALL_ACCESS, FALSE, szSem );  if( hSem == NULL )    hSem = ::CreateSemaphore( NULL, 1, 1, szSem );  return hSem;}//HANDLE hSemValue = NULL;BOOL APIENTRY DllMain( HMODULE hModule, DWORD  reason, LPVOID lpReserved ){  switch ( reason )  {  case DLL_PROCESS_ATTACH:    {      hSemValue = GiveSem( "Value" );      theList.Attach(hModule);    }    break;  case DLL_PROCESS_DETACH:    {      theList.Detach();    }    break;  };  return TRUE;}